import { AfterViewInit, Component, ElementRef, ViewChild } from '@angular/core';
import { DatePipe } from '@angular/common';
import { TableColumn, TableConfig } from 'src/app/shared/components/table-advanced';
import { CreditCardService } from 'src/app/shared/services/credit-card.service';
import { Subject, debounceTime, distinctUntilChanged, forkJoin, takeUntil } from 'rxjs';
import { HeaderService } from '../../shared/services/header.service';
import { AbstractControl, FormArray, FormBuilder, FormControl, FormGroup, Validators } from '@angular/forms';
import { ModalDismissReasons, NgbModal, NgbModalConfig } from '@ng-bootstrap/ng-bootstrap';
import { Router } from '@angular/router';
import { MessageModalComponent } from '../../shared/modals/message-modal/message-modal.component';
import { filter } from 'lodash';
import { GroupReconciliationComponent } from './components/group-reconciliation/group-reconciliation.component';
import { HelperService } from '../../shared/services/helper.service';
import { AppConfigService } from 'src/app/shared/services/app-config.service';
@Component({
  selector: 'app-create-reconciliation',
  templateUrl: './create-reconciliation.component.html',
  styleUrls: ['./create-reconciliation.component.scss'],
  providers: [DatePipe]
})
export class CreateReconciliationComponent {
  datepickerInput: any;
  searchText = new FormControl(null);
  netAmount = new FormControl(null)
  collectionDate = new FormControl(null)
  @ViewChild('myModal') event: ElementRef | undefined;
  @ViewChild('myErrorModal') eventerror: ElementRef | undefined;
  unsubscribe = new Subject<void>();
  isvalid: boolean = true
  isReturn = false;
  tableColumns: TableColumn[] = [];
  searchChequeNo: string = '';
  searchCustomerNo: string = '';
  loading = false;
  reconciliation: any[] = [];
  bankAccountList: any[] = [];
  branchList: any[] = [];
  totalAllRecordsCount = 0;
  page = 1;
  total = 0;
  limit = 6;
  sort: number = 1;
  startDate = '';
  tableConfig: TableConfig = {
    paging: true,
    filter: {
      Sort: 1,
      PageSize: this.limit,
    },
  };
  modalReference: any;
  closeResult: any;
  formGroup!: FormGroup;
  filterForm!: FormGroup;
  selectedAmount = 0;
  filterParams = '';
  currency = '';
  constructor(
    private creditcardservice: CreditCardService,
    private headerService: HeaderService,
    private modalService: NgbModal,
    public router: Router,
    private modalConfig: NgbModalConfig,
    private fb: FormBuilder,
    private _datePipe: DatePipe,
    private _helperService: HelperService,
    private appConfigService: AppConfigService
  ) {
    this.modalConfig.centered = true;
  }
  ngOnInit() {
    this.headerService.setTitle('Create Reconciliation');
    this.initFilterForm();
    this.getData()
    this.formGroup = this.fb.group({
      cardsArray: this.fb.array([])
    });
    this.fetcAllData();
    this.getBankAccountList();
    this.currency = this.appConfigService.currency || '';
  }
  getData() {
    const api1$ = this.creditcardservice.GetProviders({ pageSize: 1000, status: 2001 });
    const api2$ = this.creditcardservice.GetCards();
    const branch$ = this.creditcardservice.GetBranch({});
    forkJoin([api1$, api2$, branch$]).subscribe(
      ([result1, result2, branch]) => {
        this.provider = result1.data;
        this.cardlist = result2.data;
        this.branchList = branch.data;
      },
      (error) => {
      }, () => { this.loading = false; });
  }

  initFilterForm() {
    this.filterForm = this.fb.group({
      providerId: [null],
      collectionDate: [''],
      collectionDateFrom: [''],
      collectionDateTo: [''],
      cardTypeId: [null],
      netAmount: [''],
      last4digits: [''],
      machineID: [''],
      branchId: [null],
      status: [30001],
    })
    this.filterForm.valueChanges.pipe(debounceTime(500)).subscribe(data => {
      this.page = 1;
      let formValues = this._helperService.trim(data);
      if (formValues?.collectionDate) {
        formValues = {
          ...formValues,
          collectionDateFrom: this._datePipe.transform(formValues.collectionDate[0], 'yyyy-MM-dd'),
          collectionDateTo: this._datePipe.transform(formValues.collectionDate[1], 'yyyy-MM-dd')
        };
        delete formValues.collectionDate;
      }
      this.filterParams = new URLSearchParams(formValues).toString();
      this.fetcAllData();
    })
  }

  fetcAllData() {
    this.loading = true;

    let params = '';

    if (this.filterParams) {
      params = `${this.filterParams}&pageSize=${this.limit}&pageNo=${this.page - 1}&sort=${this.sort}`;
    } else {
      params = `status=${30001}&pageSize=${this.limit}&pageNo=${this.page - 1}&sort=${this.sort}`;
    }

    this.creditcardservice.GetReconHistory(params).subscribe(result => {
      if (result) {
        this.reconciliation = result.data || [];
        this.totalAllRecordsCount = result?.totalRecordCount;
        this.total = result?.totalRecordCount;

        this.cardsArray.clear();

        this.reconciliation = this.reconciliation.map((element: any) => {
          this.cardsArray.push(this.initFormGroup(element));

          return {
            ...element,
            checked: false
          };
        });
      }
    }).add(() => (this.loading = false));
  }

  getBankAccountList() {
    this.creditcardservice.getBankAccounts(`pageSize=1000&status=2001&accountType=15010`).subscribe(response => {
      this.bankAccountList = response.data;
    })
  }
  get cardsArray() {
    return this.formGroup.get('cardsArray') as FormArray;
  }
  getNotReturnedCardTransactions() {
    let filtered = this.cardsArray.getRawValue().filter(value => value?.reconcilationIds > 0);
    if (filtered.length)
      this.isReturn = filtered.every(value => !value.isReturn);
  }
  groupReconciliation() {
    let cardIds = this.cardsArray.getRawValue().filter(value => value?.reconcilationIds > 0 && !value.isReturn);
    const modalRef = this.modalService.open(GroupReconciliationComponent, { size: 'lg' });
    modalRef.componentInstance.data = { cardIds, totalAmount: this.selectedAmount };
    modalRef.componentInstance.eventData.subscribe((value: any) => {
      //let comPercentage = value?.commissionPercentage;
      //this.cardsArray.controls.forEach((control: AbstractControl, index: number) => {
      //  let reconcilationId = control.get('reconcilationIds')?.value;
      //  if (reconcilationId) {
      //    let amount = +this.reconciliation[index].cardCollectionJod;
      //    let comAmount = +(amount * comPercentage / 100)
      //    control.get('comissionPercentage')?.setValue(comPercentage);
      //    control.get('comissionAmount')?.setValue(comAmount.toFixed(3));
      //    control.get('netAmount')?.setValue((amount - comAmount).toFixed(3));
      //  }
      //})
      this.selectedAmount = 0;
      this.isReturn = false;
      this.fetcAllData();
      modalRef.dismiss();
    })
  }
  initFormGroup(item?: any) {
    const formGroup = this.fb.group({
      reconcilationIds: [null],
      //comissionPercentage: ['0'],
      comissionAmount: [''],
      netAmount: [null],
      bankaccountID: [null],
      depositDate: [new Date()],
      checked: [false],
      isReturn: [item?.isReturn], //Readonly
      cardCollectionJod: [item?.cardCollectionJod], //Readonly
    });
    if (item && item.isReturn) {
      formGroup.get('comissionAmount')?.setValue('0');
      formGroup.get('comissionAmount')?.disable();
      formGroup.get('netAmount')?.setValue(item?.collectedAmount);
      formGroup.get('netAmount')?.disable();
    }
    return formGroup;
  }
  handleCommissionAmountChange(event: any, index: number, row: any) {
    let commissionAmount = event.target.value;
    if (commissionAmount) {
      let amount = row?.cardCollectionJod;
      if (commissionAmount > amount) {
        this.cardsArray.at(index).get('comissionAmount')?.setErrors({ amountExceeded: true });
        return;
      }
      this.cardsArray.at(index).get('netAmount')?.setValue((amount - commissionAmount).toFixed(3));
    }
  }
  handleNetAmountChange(event: any, index: number, row: any) {
    let netAmount = event.target.value;
    if (netAmount) {
      let amount = row?.cardCollectionJod;
      if (netAmount > amount) {
        this.cardsArray.at(index).get('netAmount')?.setErrors({ amountExceeded: true });
        return;
      }
      this.cardsArray.at(index).get('comissionAmount')?.setValue((amount - netAmount).toFixed(3));
    }
  }
  checkAll(event: any) {
    let checked = event.target.checked;
    this.selectedAmount = 0;
    this.reconciliation.forEach((x: any, index: number) => {
      if (checked) {
        this.cardsArray.at(index).get('checked')?.setValue(true);
        this.cardsArray.at(index).get('reconcilationIds')?.setValue(x?.ordersCardsCollectionId);
        this.setValidator('comissionAmount', Validators.required, index);
        this.setValidator('netAmount', Validators.required, index);
        this.setValidator('depositDate', Validators.required, index);
        this.setValidator('bankaccountID', Validators.required, index);
        this.selectedAmount += x.cardCollectionJod
      }
      else {
        this.cardsArray.at(index).get('checked')?.setValue(false);
        this.cardsArray.at(index).get('reconcilationIds')?.setValue(null);
        this.setValidator('comissionAmount', null, index);
        this.setValidator('netAmount', null, index);
        this.setValidator('depositDate', null, index);
        this.setValidator('bankaccountID', null, index);
      }
    })
    this.getNotReturnedCardTransactions()
  }
  handleChangeCheckBox(event: any, item: any, index: number) {
    let checked = event.target.checked;
    if (checked) {
      this.cardsArray.at(index).get('reconcilationIds')?.setValue(item?.ordersCardsCollectionId);
      this.setValidator('comissionAmount', Validators.required, index);
      this.setValidator('netAmount', Validators.required, index);
      this.setValidator('bankaccountID', Validators.required, index);
      this.selectedAmount += item?.cardCollectionJod;
    }
    else {
      this.cardsArray.at(index).get('reconcilationIds')?.setValue(null);
      this.setValidator('comissionAmount', null, index);
      this.setValidator('netAmount', null, index);
      this.setValidator('depositDate', null, index);
      this.setValidator('bankaccountID', null, index);
      this.selectedAmount -= item?.cardCollectionJod;
    }
    this.getNotReturnedCardTransactions()
  }
  setValidator(controlName: string, validator: any, index: number) {
    const control = this.cardsArray.at(index).get(controlName);
    if (control && validator) {
      control.setValidators(validator);
      control.updateValueAndValidity();
    }
    else if (!validator) {
      control?.clearValidators();
      control?.updateValueAndValidity();
    }
  }
  onPostReconcilationIds() {
    let data = this.cardsArray.getRawValue().filter((x: any) => x.checked).map((item: any) => {
      return {
        reconcilationIds: item?.reconcilationIds,
        commission: item?.comissionAmount,
        cardCollectionJodNet: item?.netAmount,
        cardBankDepositDate: item?.depositDate,
        bankaccountID: item?.bankaccountID,
      }
    })
    this.creditcardservice.ReconcilationIds(data).subscribe(result => {
      if (result.isSuccess) {
        this.responseModal('success', `Reconciliation successfully done.`);
        this.fetcAllData();
        this.selectedAmount = 0;
      }
    }, err => {
      this.responseModal('error', err?.error?.errors[0]?.ErrorMessageEn)
    }).add(() => (this.loading = false));
  }
  responseModal(type: any, message: any) {
    const ref = this.modalService.open(MessageModalComponent);
    ref.componentInstance.type = type;
    ref.componentInstance.message = message;
  }
  openmdel() {
    this.modalService.open(this.event, { ariaLabelledBy: 'modal-basic-title' }).result.then(
      (result) => {
        this.closeResult = `Closed with: ${result}`;
      },
      (reason) => {
        this.closeResult = `Dismissed ${this.getDismissReason(reason)}`;
      },
    );
  }
  openmdelerroe() {
    this.modalService.open(this.eventerror, { ariaLabelledBy: 'modal-basic-title' }).result.then(
      (result) => {
        this.closeResult = `Closed with: ${result}`;
      },
      (reason) => {
        this.closeResult = `Dismissed ${this.getDismissReason(reason)}`;
      },
    );
  }
  private getDismissReason(reason: any): string {
    if (reason === ModalDismissReasons.ESC) {
      return 'by pressing ESC';
    } else if (reason === ModalDismissReasons.BACKDROP_CLICK) {
      return 'by clicking on a backdrop';
    } else {
      return `with: ${reason}`;
    }
  }
  selecteddata: any[] = [];
  sortByCardLast4Digits() {
    if (this.sort == 3) this.sort = 1;
    else {
      this.sort = this.sort == 2 ? 3 : 2
    };
    this.fetcAllData();
  }
  sortByProviderName() {
    if (this.sort == 5) this.sort = 1; else this.sort = this.sort == 4 ? 5 : 4;
    this.fetcAllData();
  }
  sortByOrderCollectionId() {
    if (this.sort == 7) this.sort = 1; else this.sort = this.sort == 6 ? 7 : 6;
    this.fetcAllData();
  }
  sortByCollectionAt() {
    if (this.sort == 9) this.sort = 1; else this.sort = this.sort == 8 ? 9 : 8;
    this.fetcAllData();
  }
  sortByBranchName() {
    if (this.sort == 11) this.sort = 1; else this.sort = this.sort == 10 ? 11 : 10;
    this.fetcAllData();
  }
  sortByRegisterName() {
    if (this.sort == 11) this.sort = 1; else this.sort = this.sort == 10 ? 11 : 10;
    this.fetcAllData();
  }
  sortByCardType() {
    if (this.sort == 13) this.sort = 1; else this.sort = this.sort == 12 ? 13 : 12;
    this.fetcAllData();
  }
  sortByCardCollectionJod() {
    if (this.sort == 15) this.sort = 1; else this.sort = this.sort == 14 ? 15 : 14;
    this.fetcAllData();
  }
  onPageChange(page: number) {
    this.page = page;
    this.fetcAllData();
  }
  provider: any[] = [];
  cardlist: any[] = [];

  modelClose(num: any) {
    if (num == 1) {
      this.modalService.dismissAll();
      this.router.navigate(['credit-card'], { queryParams: { num: 2 } });
    }
    else {
      this.modalService.dismissAll();

    }

  }
  erromessage: any

  validateInput(event: any) {
    const enteredValue = event.target.value;
    const pattern = /^[0-9]*\.?[0-9]*$/; // Regex pattern to allow numbers and decimal point
    if (!pattern.test(enteredValue)) {
      event.target.value = enteredValue.replace(/[^0-9.]/g, ''); // Remove any invalid characters
    }
  }
}
